window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch02"]={"id": "ch02", "title": "第二章 生物学数据库及其检索", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第二章 生物学数据库及其检索", "slides": [{"i": 0, "sec": "第一节 生物学数据库简介", "title": "数据库、记录、字段与值", "notes": "数据库（database）是按一定结构组织、统一管理的数据集合，便于检索与调用。其基本单位是记录（record/entry），一条记录描述一个实体（如一条序列、一个蛋白质）。记录由若干字段（field）组成，字段是描述属性的类别，如基因名、物种、创建日期；值（value）是字段的具体内容。检索的本质是用查询语言在库中查找满足“特定字段包含特定内容”条件的记录。例如在GenBank中检索物种为人（Homo sapiens）、近30天公布、分子类型为mRNA的核酸序列。易错点：字段是属性类别，值是具体内容，二者不可混淆；记录与条目同义。", "page": 11, "level": "掌握", "img": "assets/img/ch02/p011.jpg", "anim": null, "fig": null, "points": ["生物学数据库采用4种结构类型：平面文件（flat file）、关系型数据库、面向对象数据库和基于Internet的XML。", "最早的数据库用平面文件格式保存，以特殊分隔符区分记录与字段，本质是长文本文件，检索时需通读整个文件，记录增多或字段复杂时检索困难。", "为帮助寻找记录间隐含关系，引入数据库管理系统（DBMS），分为关系型（RDBMS）和对象型（OODBMS）。", "关系型以表、行、列组织数据，通过键建立关联。"], "check": {"q": "关于生物学数据库的基本组成，下列说法正确的是？", "o": ["A. 数据库的基本单位是字段，一条字段描述一个实体", "B. 记录由若干数据库组成，数据库由若干值组成", "C. 数据库的基本单位是记录，记录由若干字段组成，字段的具体内容称为值", "D. 检索的本质是通读整个数据库文件，无需指定字段条件"], "a": "C", "e": "数据库的基本单位是记录，一条记录描述一个实体；记录由若干字段组成，字段是描述属性的类别；值是字段的具体内容。检索的本质是用查询语言查找满足“特定字段包含特定内容”条件的记录。"}, "cards": [{"front": "生物学数据库的基本单位是什么？它由什么组成？", "back": "基本单位是记录（record/entry），一条记录描述一个实体（如一条序列、一个蛋白质）。记录由若干字段（field）组成，字段是描述属性的类别，如基因名、物种、创建日期；值（value）是字段的具体内容。", "mnemonic": "记录含字段，字段有值", "useImg": false}, {"front": "生物学数据库有哪4种结构类型？", "back": "平面文件（flat file）、关系型数据库、面向对象数据库和基于Internet的XML。", "mnemonic": "平关对X", "useImg": false}]}, {"i": 1, "sec": "第一节 生物学数据库简介", "title": "数据库结构类型：平面文件、关系型、对象型与XML", "notes": "生物学数据库采用4种结构类型：平面文件（flat file）、关系型数据库、面向对象数据库和基于Internet的XML。最早的数据库用平面文件格式保存，以特殊分隔符区分记录与字段，本质是长文本文件，检索时需通读整个文件，记录增多或字段复杂时检索困难。为帮助寻找记录间隐含关系，引入数据库管理系统（DBMS），分为关系型（RDBMS）和对象型（OODBMS）。关系型以表、行、列组织数据，通过键建立关联，支持SQL查询；对象型适合复杂嵌套数据。XML以标签描述层次结构，便于网络交换。", "page": 11, "level": "理解", "img": "assets/img/ch02/p011.jpg", "anim": null, "fig": null, "points": ["生物学数据库采用4种结构类型：平面文件（flat file）、关系型数据库、面向对象数据库和基于Internet的XML。", "最早的数据库用平面文件格式保存，以特殊分隔符区分记录与字段，本质是长文本文件，检索时需通读整个文件，记录增多或字段复杂时检索困难。", "为帮助寻找记录间隐含关系，引入数据库管理系统（DBMS），分为关系型（RDBMS）和对象型（OODBMS）。", "关系型以表、行、列组织数据，通过键建立关联。"], "check": {"q": "关于生物学数据库的结构类型，下列描述正确的是？", "o": ["A. 平面文件格式通过键建立表间关联，支持SQL查询", "B. 关系型数据库以表、行、列组织数据，通过键建立关联并支持SQL查询", "C. 面向对象数据库只适合存储简单文本，不适合复杂嵌套数据", "D. XML格式不能用于网络数据交换"], "a": "B", "e": "关系型数据库以表、行、列组织数据，通过键建立关联，支持SQL查询；平面文件本质是长文本文件，检索时需通读整个文件；对象型适合复杂嵌套数据；XML适合网络交换。"}, "cards": [{"front": "生物学数据库的基本单位是什么？它由什么组成？", "back": "基本单位是记录（record/entry），一条记录描述一个实体（如一条序列、一个蛋白质）。记录由若干字段（field）组成，字段是描述属性的类别，如基因名、物种、创建日期；值（value）是字段的具体内容。", "mnemonic": "记录含字段，字段有值", "useImg": false}, {"front": "生物学数据库有哪4种结构类型？", "back": "平面文件（flat file）、关系型数据库、面向对象数据库和基于Internet的XML。", "mnemonic": "平关对X", "useImg": false}]}, {"i": 2, "sec": "第一节 生物学数据库简介", "title": "生物学数据库的分类：按数据类型", "notes": "按存放数据类型，生物学数据库可分为：序列数据库（如GenBank、Swiss-Prot）、三维结构数据库（如PDB）、文献数据库（如NCBI PubMed）、序列特征数据库（如PROSITE、Pfam）、基因组图谱数据库（如MapViewer、Ensembl）、表达谱数据库等，每类还可细分。按存储内容层次又分为一级数据库、二级数据库和专用数据库。分类的意义在于帮助用户根据研究问题选择合适的数据源；同一数据可能存在于多个库中，需注意版本与注释差异。", "page": 12, "level": "理解", "img": "assets/img/ch02/p012.jpg", "anim": null, "fig": null, "points": ["一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。", "二级数据库在一级数据库基础上经计算加工并增加人工注释，如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）。", "二级库功能与结构注释更完善，便于直接用于分析。"], "check": {"q": "按存放数据类型分类，PDB属于哪一类生物学数据库？", "o": ["A. 序列数据库", "B. 文献数据库", "C. 三维结构数据库", "D. 表达谱数据库"], "a": "C", "e": "按数据类型分类，PDB属于三维结构数据库；GenBank、Swiss-Prot属于序列数据库；NCBI PubMed属于文献数据库；PROSITE、Pfam属于序列特征数据库。"}, "cards": [{"front": "按存放数据类型，生物学数据库可分为哪些主要类别？各举一例。", "back": "序列数据库（如GenBank、Swiss-Prot）、三维结构数据库（如PDB）、文献数据库（如NCBI PubMed）、序列特征数据库（如PROSITE、Pfam）、基因组图谱数据库（如MapViewer、Ensembl）、表达谱数据库等。", "mnemonic": "序结文特图表", "useImg": false}, {"front": "什么是一级数据库和二级数据库？各举一例。", "back": "一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如GenBank、EMBL、DDBJ、PDB。二级数据库在一级数据库基础上经计算加工并增加人工注释，如RefSeq、UniProt KnowledgeBase（Swiss-Prot与TrEMBL组成）。", "mnemonic": "一级原始，二级加工", "useImg": false}]}, {"i": 3, "sec": "第一节 生物学数据库简介", "title": "一级数据库与二级数据库", "notes": "一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。二级数据库在一级数据库基础上经计算加工并增加人工注释，如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）。二级库功能与结构注释突出，但自动计算注释可能误导，使用时需谨慎。易错点：二级库注释不等于实验证实。", "page": 12, "level": "掌握", "img": "assets/img/ch02/p012.jpg", "anim": null, "fig": null, "points": ["一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。", "二级数据库在一级数据库基础上经计算加工并增加人工注释，如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）。", "二级库功能与结构注释更完善，便于直接用于分析。"], "check": {"q": "关于一级数据库与二级数据库，下列说法正确的是？", "o": ["A. 一级数据库是在二级数据库基础上经计算加工形成的", "B. GenBank、EMBL、DDBJ和PDB属于一级数据库", "C. RefSeq和UniProt KnowledgeBase属于一级数据库", "D. 二级数据库只包含实验原始数据，不含人工注释"], "a": "B", "e": "一级数据库属档案数据库，内容主要是实验原始数据及基本说明，如GenBank、EMBL、DDBJ和PDB；二级数据库在一级数据库基础上经计算加工并增加人工注释，如RefSeq和UniProt KnowledgeBase。"}, "cards": [{"front": "按存放数据类型，生物学数据库可分为哪些主要类别？各举一例。", "back": "序列数据库（如GenBank、Swiss-Prot）、三维结构数据库（如PDB）、文献数据库（如NCBI PubMed）、序列特征数据库（如PROSITE、Pfam）、基因组图谱数据库（如MapViewer、Ensembl）、表达谱数据库等。", "mnemonic": "序结文特图表", "useImg": false}, {"front": "什么是一级数据库和二级数据库？各举一例。", "back": "一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如GenBank、EMBL、DDBJ、PDB。二级数据库在一级数据库基础上经计算加工并增加人工注释，如RefSeq、UniProt KnowledgeBase（Swiss-Prot与TrEMBL组成）。", "mnemonic": "一级原始，二级加工", "useImg": false}]}, {"i": 4, "sec": "第二节 生物学数据库的数据存储格式", "title": "平面文件格式（Flat File）的特点", "notes": "平面文件格式即纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode。数据被组织为若干Entry（记录/条目），每个Entry描述一个数据实体，如UniProt中一个Entry对应一个蛋白质的序列及描述。正文行中每列对应明确定义的格式。Entry可全部存于单一文本，也可各自单独成文件，大库常两者结合。优势是通用性强：几乎所有计算机都能读写文本，自定义解析程序简单，跨平台、便于FTP或电子邮件传输。缺点是存储空间利用率不占优，网络传输时紧凑性成为瓶颈。", "page": 19, "level": "掌握", "img": "assets/img/ch02/p019.jpg", "anim": null, "fig": null, "points": ["信息存储需控制两方面：数据编译为字节的方式（数据格式）以及能编码/解码该数据的程序。", "二者紧密相关：复杂全能格式若无现成程序支持则无意义；过于简单紧凑的格式又限制数据操作功能。", "平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。", "当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。", "因此格式选择需在通用性、可解析性、存储效率与传输效率之间权衡，这是生物信息学数据管理面临的难题之一。"], "check": {"q": "关于平面文件格式的特点，下列说法错误的是？", "o": ["A. 通常使用ASCII字符，也可含扩展ASCII或Unicode", "B. 数据被组织为若干Entry，每个Entry描述一个数据实体", "C. 通用性强，几乎所有计算机都能读写文本，便于跨平台传输", "D. 存储空间利用率高，记录增多或字段复杂时检索更容易"], "a": "D", "e": "平面文件的缺点是存储空间利用率不高，记录增多或字段复杂时检索困难；其优势是通用性强、跨平台、便于FTP或电子邮件传输。"}, "cards": [{"front": "平面文件格式（Flat File）的主要特点是什么？", "back": "纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode。数据组织为若干Entry（记录/条目），每个Entry描述一个数据实体。正文行中每列对应明确定义的格式。Entry可全部存于单一文本，也可各自单独成文件。优势是通用性强，几乎所有计算机都能读写文本，自定义解析程序简单，跨平台、便于FTP传输。", "mnemonic": "纯文本、分Entry、列定格式、通用强", "useImg": false}, {"front": "UniProt平面文件Entry中，ID行、AC行、DE行、GN行、OS行、OX行分别代表什么？", "back": "ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OX行给出NCBI TaxID。", "mnemonic": "ID标识，AC登录，DE描述，GN基因，OS物种，OX分类ID", "useImg": false}, {"front": "XML格式与关系型数据库存储各有什么优缺点？", "back": "XML用成对标签描述数据的层次结构，兼具可读性与机器可解析性，适合表示复杂嵌套信息及网络交换，但文件较冗长。关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高。", "mnemonic": "XML层次可读但冗长，关系表高效但模式固定", "useImg": false}, {"front": "数据格式选择需在哪些方面进行权衡？", "back": "需在通用性、可解析性、存储效率与传输效率之间权衡。平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。", "mnemonic": "通用、可解析、存储、传输", "useImg": false}]}, {"i": 5, "sec": "第二节 生物学数据库的数据存储格式", "title": "UniProt平面文件Entry的结构与字段标识符", "notes": "UniProt的Flat File Entry由一系列文本行组成，以“//”表示Entry结束。每行开头为两个字符的字段标识符，用于区分Entry的不同部分：ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DT行记录日期与版本；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI TaxID；RN/RP/RX/RA/RT/RL行描述文献。理解字段标识符是解析平面文件、编写脚本提取信息的基础。", "page": 19, "level": "掌握", "img": "assets/img/ch02/p019.jpg", "anim": null, "fig": null, "points": ["信息存储需控制两方面：数据编译为字节的方式（数据格式）以及能编码/解码该数据的程序。", "二者紧密相关：复杂全能格式若无现成程序支持则无意义；过于简单紧凑的格式又限制数据操作功能。", "平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。", "当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。", "因此格式选择需在通用性、可解析性、存储效率与传输效率之间权衡，这是生物信息学数据管理面临的难题之一。"], "check": {"q": "在UniProt平面文件Entry中，用于表示Entry结束的符号是？", "o": ["A. //", "B. ##", "C. --", "D. **"], "a": "A", "e": "UniProt的Flat File Entry由一系列文本行组成，以“//”表示Entry结束；每行开头为两个字符的字段标识符，如ID、AC、DT、DE、GN、OS、OC、OX等。"}, "cards": [{"front": "平面文件格式（Flat File）的主要特点是什么？", "back": "纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode。数据组织为若干Entry（记录/条目），每个Entry描述一个数据实体。正文行中每列对应明确定义的格式。Entry可全部存于单一文本，也可各自单独成文件。优势是通用性强，几乎所有计算机都能读写文本，自定义解析程序简单，跨平台、便于FTP传输。", "mnemonic": "纯文本、分Entry、列定格式、通用强", "useImg": false}, {"front": "UniProt平面文件Entry中，ID行、AC行、DE行、GN行、OS行、OX行分别代表什么？", "back": "ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OX行给出NCBI TaxID。", "mnemonic": "ID标识，AC登录，DE描述，GN基因，OS物种，OX分类ID", "useImg": false}, {"front": "XML格式与关系型数据库存储各有什么优缺点？", "back": "XML用成对标签描述数据的层次结构，兼具可读性与机器可解析性，适合表示复杂嵌套信息及网络交换，但文件较冗长。关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高。", "mnemonic": "XML层次可读但冗长，关系表高效但模式固定", "useImg": false}, {"front": "数据格式选择需在哪些方面进行权衡？", "back": "需在通用性、可解析性、存储效率与传输效率之间权衡。平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。", "mnemonic": "通用、可解析、存储、传输", "useImg": false}]}, {"i": 6, "sec": "第二节 生物学数据库的数据存储格式", "title": "XML格式与关系型数据库存储", "notes": "XML（可扩展标记语言）用成对标签描述数据的层次结构，兼具可读性与机器可解析性，适合表示复杂嵌套信息及网络交换，但文件较冗长。关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询。其优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高。生物信息学中常见的关系型数据库实例有Ensembl和Gene Ontology数据库。", "page": 19, "level": "理解", "img": "assets/img/ch02/p019.jpg", "anim": null, "fig": null, "points": ["信息存储需控制两方面：数据编译为字节的方式（数据格式）以及能编码/解码该数据的程序。", "二者紧密相关：复杂全能格式若无现成程序支持则无意义；过于简单紧凑的格式又限制数据操作功能。", "平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。", "当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。", "因此格式选择需在通用性、可解析性、存储效率与传输效率之间权衡，这是生物信息学数据管理面临的难题之一。"], "check": {"q": "关于XML格式与关系型数据库存储，下列说法正确的是？", "o": ["A. XML用成对标签描述数据的层次结构，适合表示复杂嵌套信息及网络交换", "B. 关系型数据库不需要预先定义结构，模式变更成本低", "C. XML文件通常比平面文件更简短，不冗长", "D. Ensembl和Gene Ontology数据库不是关系型数据库"], "a": "A", "e": "XML用成对标签描述数据的层次结构，兼具可读性与机器可解析性，适合表示复杂嵌套信息及网络交换，但文件较冗长；关系型数据库结构需预先定义，模式变更成本高；Ensembl和Gene Ontology数据库是常见关系型数据库实例。"}, "cards": [{"front": "平面文件格式（Flat File）的主要特点是什么？", "back": "纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode。数据组织为若干Entry（记录/条目），每个Entry描述一个数据实体。正文行中每列对应明确定义的格式。Entry可全部存于单一文本，也可各自单独成文件。优势是通用性强，几乎所有计算机都能读写文本，自定义解析程序简单，跨平台、便于FTP传输。", "mnemonic": "纯文本、分Entry、列定格式、通用强", "useImg": false}, {"front": "UniProt平面文件Entry中，ID行、AC行、DE行、GN行、OS行、OX行分别代表什么？", "back": "ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OX行给出NCBI TaxID。", "mnemonic": "ID标识，AC登录，DE描述，GN基因，OS物种，OX分类ID", "useImg": false}, {"front": "XML格式与关系型数据库存储各有什么优缺点？", "back": "XML用成对标签描述数据的层次结构，兼具可读性与机器可解析性，适合表示复杂嵌套信息及网络交换，但文件较冗长。关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高。", "mnemonic": "XML层次可读但冗长，关系表高效但模式固定", "useImg": false}, {"front": "数据格式选择需在哪些方面进行权衡？", "back": "需在通用性、可解析性、存储效率与传输效率之间权衡。平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。", "mnemonic": "通用、可解析、存储、传输", "useImg": false}]}, {"i": 7, "sec": "第二节 生物学数据库的数据存储格式", "title": "数据格式的通用性与紧凑性权衡", "notes": "信息存储需控制两方面：数据编译为字节的方式（数据格式）以及能编码/解码该数据的程序。二者紧密相关：复杂全能格式若无现成程序支持则无意义；过于简单紧凑的格式又限制数据操作功能。平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。因此格式选择需在通用性、可解析性、存储效率与传输效率之间权衡，这是生物信息学数据管理面临的难题之一。", "page": 19, "level": "理解", "img": "assets/img/ch02/p019.jpg", "anim": null, "fig": null, "points": ["信息存储需控制两方面：数据编译为字节的方式（数据格式）以及能编码/解码该数据的程序。", "二者紧密相关：复杂全能格式若无现成程序支持则无意义；过于简单紧凑的格式又限制数据操作功能。", "平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。", "当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。", "因此格式选择需在通用性、可解析性、存储效率与传输效率之间权衡，这是生物信息学数据管理面临的难题之一。"], "check": {"q": "关于数据格式的通用性与紧凑性权衡，下列说法正确的是？", "o": ["A. 复杂全能格式即使没有现成程序支持也有意义", "B. 过于简单紧凑的格式不会限制数据操作功能", "C. 当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要", "D. 格式选择只需考虑存储效率，不需要考虑通用性和可解析性"], "a": "C", "e": "信息存储需控制数据格式以及能编码/解码该数据的程序；复杂全能格式若无现成程序支持则无意义，过于简单紧凑的格式又限制数据操作功能；网络传输时传输速度成为瓶颈，格式紧凑性变得重要，因此需在通用性、可解析性、存储效率与传输效率之间权衡。"}, "cards": [{"front": "平面文件格式（Flat File）的主要特点是什么？", "back": "纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode。数据组织为若干Entry（记录/条目），每个Entry描述一个数据实体。正文行中每列对应明确定义的格式。Entry可全部存于单一文本，也可各自单独成文件。优势是通用性强，几乎所有计算机都能读写文本，自定义解析程序简单，跨平台、便于FTP传输。", "mnemonic": "纯文本、分Entry、列定格式、通用强", "useImg": false}, {"front": "UniProt平面文件Entry中，ID行、AC行、DE行、GN行、OS行、OX行分别代表什么？", "back": "ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OX行给出NCBI TaxID。", "mnemonic": "ID标识，AC登录，DE描述，GN基因，OS物种，OX分类ID", "useImg": false}, {"front": "XML格式与关系型数据库存储各有什么优缺点？", "back": "XML用成对标签描述数据的层次结构，兼具可读性与机器可解析性，适合表示复杂嵌套信息及网络交换，但文件较冗长。关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高。", "mnemonic": "XML层次可读但冗长，关系表高效但模式固定", "useImg": false}, {"front": "数据格式选择需在哪些方面进行权衡？", "back": "需在通用性、可解析性、存储效率与传输效率之间权衡。平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。", "mnemonic": "通用、可解析、存储、传输", "useImg": false}]}, {"i": 8, "sec": "第三节 生物学数据库的检索", "title": "关系型数据库建模、规范化与RDBMS", "notes": "关系型数据库设计需进行建模与规范化。规范化指通过分解表减少数据冗余，已定义多个逐级完善的等级；实践目标是在冗余与性能之间取得最佳平衡，最理想结果取决于数据库系统类型、使用频率或最常用登录方法。建模结果是数据库结构纲目（schema），标记表及表间关系，定义每张表每一列的细节及表列间的约束。实现数据关联的系统称为关系型数据库管理系统（RDBMS），如Oracle、MySQL、Microsoft SQL Server；MySQL开源，适合中小型生物数据库搭建。", "page": 29, "level": "理解", "img": "assets/img/ch02/p029.jpg", "anim": null, "fig": null, "points": ["Entrez由NCBI开发维护，是目前应用最广泛的生物学数据库检索系统之一。", "它利用公共数据库各记录间本身存在的逻辑关系，从多种类型数据的文本信息中找到所需信息。", "Entrez数据库模型中，圆圈表示各数据库，颜色深浅表示数据量多少；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）。", "各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录。"], "check": {"q": "关于关系型数据库建模、规范化与RDBMS，下列说法正确的是？", "o": ["A. 规范化指通过分解表增加数据冗余", "B. 建模结果是数据库结构纲目（schema），标记表及表间关系", "C. RDBMS不能实现数据关联", "D. MySQL是商业闭源数据库，不适合中小型项目"], "a": "B", "e": "规范化指通过分解表减少数据冗余；建模结果是数据库结构纲目（schema），标记表及表间关系，定义每张表每一列的细节及表列间的约束；实现数据关联的系统称为RDBMS，如Oracle、MySQL、Microsoft SQL Server；MySQL开源，适合中小型项目。"}, "cards": [{"front": "什么是关系型数据库的规范化？其目标是什么？", "back": "规范化指通过分解表减少数据冗余，已定义多个逐级完善的等级。实践目标是在冗余与性能之间取得最佳平衡，最理想结果取决于数据库系统类型、使用频率或最常用登录方法。", "mnemonic": "分解表、减冗余、平衡性能", "useImg": false}, {"front": "Ensembl和Gene Ontology数据库各有什么特点？", "back": "Ensembl由EBI与Wellcome Trust Sanger Institute联合开发，是基因注释数据库，真核生物基因组数据主要集中在脊椎动物。数据可直接访问MySQL服务器获取，但因结构纲目复杂，通常建议通过专用Perl API访问。Gene Ontology数据库也是基于MySQL分布的关系型数据库，将基因组术语整理成本体结构，建立在细胞成分、生物过程、分子功能三个层面。", "mnemonic": "Ensembl脊椎注释，GO三层面本体", "useImg": false}, {"front": "Entrez系统中硬连接（hard link）和软连接（soft link）分别指什么？", "back": "硬连接指点击圆圈显示与其他数据库的链接信息，即不同数据库之间的链接。软连接又称neighbor，指各数据库内部数据间预先运算好的与某记录相似的其他记录。", "mnemonic": "硬连跨库，软连库内相似", "useImg": false}]}, {"i": 9, "sec": "第三节 生物学数据库的检索", "title": "生物信息学关系型数据库实例：Ensembl与Gene Ontology", "notes": "Ensembl由EBI与Wellcome Trust Sanger Institute联合开发，是基因注释数据库，真核生物基因组数据主要集中在脊椎动物。数据可直接访问MySQL服务器获取，但因结构纲目复杂，通常建议通过专用Perl API访问。Gene Ontology数据库也是基于MySQL分布的关系型数据库，将基因组术语整理成本体结构——条目间基于特定标准形成的关系网络，建立在细胞成分、生物过程和分子功能三大标准及“等价”“属于”等关系界定之上。GO数据库包含基因产物功能的直接信息及与其他公共数据库（如序列）的关联信息。", "page": 29, "level": "理解", "img": "assets/img/ch02/p029.jpg", "anim": null, "fig": null, "points": ["Entrez由NCBI开发维护，是目前应用最广泛的生物学数据库检索系统之一。", "它利用公共数据库各记录间本身存在的逻辑关系，从多种类型数据的文本信息中找到所需信息。", "Entrez数据库模型中，圆圈表示各数据库，颜色深浅表示数据量多少；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）。", "各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录。"], "check": {"q": "关于Ensembl与Gene Ontology数据库，下列说法正确的是？", "o": ["A. Ensembl由NCBI独立开发，主要收录原核生物基因组数据", "B. Ensembl数据不能通过MySQL服务器访问", "C. Gene Ontology数据库将基因组术语整理成本体结构，建立在细胞成分、生物过程和分子功能三大标准上", "D. Gene Ontology数据库不是基于MySQL分布的关系型数据库"], "a": "C", "e": "Ensembl由EBI与Wellcome Trust Sanger Institute联合开发，是基因注释数据库，真核生物基因组数据主要集中在脊椎动物，数据可直接访问MySQL服务器获取，通常建议通过专用Perl API访问；Gene Ontology数据库也是基于MySQL分布的关系型数据库，将基因组术语整理成本体结构，建立在细胞成分、生物过程和分子功能三大标准及“等价”“属于”等关系上。"}, "cards": [{"front": "什么是关系型数据库的规范化？其目标是什么？", "back": "规范化指通过分解表减少数据冗余，已定义多个逐级完善的等级。实践目标是在冗余与性能之间取得最佳平衡，最理想结果取决于数据库系统类型、使用频率或最常用登录方法。", "mnemonic": "分解表、减冗余、平衡性能", "useImg": false}, {"front": "Ensembl和Gene Ontology数据库各有什么特点？", "back": "Ensembl由EBI与Wellcome Trust Sanger Institute联合开发，是基因注释数据库，真核生物基因组数据主要集中在脊椎动物。数据可直接访问MySQL服务器获取，但因结构纲目复杂，通常建议通过专用Perl API访问。Gene Ontology数据库也是基于MySQL分布的关系型数据库，将基因组术语整理成本体结构，建立在细胞成分、生物过程、分子功能三个层面。", "mnemonic": "Ensembl脊椎注释，GO三层面本体", "useImg": false}, {"front": "Entrez系统中硬连接（hard link）和软连接（soft link）分别指什么？", "back": "硬连接指点击圆圈显示与其他数据库的链接信息，即不同数据库之间的链接。软连接又称neighbor，指各数据库内部数据间预先运算好的与某记录相似的其他记录。", "mnemonic": "硬连跨库，软连库内相似", "useImg": false}]}, {"i": 10, "sec": "第三节 生物学数据库的检索", "title": "NCBI Entrez系统概述", "notes": "Entrez由NCBI开发维护，是目前应用最广泛的生物学数据库检索系统之一。它利用公共数据库各记录间本身存在的逻辑关系，从多种类型数据的文本信息中找到所需信息。Entrez数据库模型中，圆圈表示各数据库，颜色深浅表示数据量多少；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）。各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录，例如核酸序列经BLAST预运算后每条记录都有相关序列（related sequence）。", "page": 29, "level": "掌握", "img": "assets/img/ch02/p029.jpg", "anim": null, "fig": null, "points": ["Entrez由NCBI开发维护，是目前应用最广泛的生物学数据库检索系统之一。", "它利用公共数据库各记录间本身存在的逻辑关系，从多种类型数据的文本信息中找到所需信息。", "Entrez数据库模型中，圆圈表示各数据库，颜色深浅表示数据量多少；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）。", "各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录。"], "check": {"q": "关于NCBI Entrez系统，下列说法正确的是？", "o": ["A. Entrez数据库中圆圈颜色深浅表示数据库建立时间早晚", "B. 点击圆圈显示与其他数据库的链接信息，属硬连接", "C. 各数据库内部数据间存在硬连接，又称neighbor", "D. 软连接指预先运算好的与某记录相似的其他记录，如核酸序列经BLAST预运算后的相似记录"], "a": "D", "e": "Entrez数据库模型中，圆圈表示各数据库，颜色深浅表示数据量多少；点击圆圈显示与其他数据库的链接信息，属硬连接；各数据库内部数据间存在软连接，又称neighbor，指预先运算好的与某记录相似的其他记录，例如核酸序列经BLAST预运算后的相似记录。"}, "cards": [{"front": "什么是关系型数据库的规范化？其目标是什么？", "back": "规范化指通过分解表减少数据冗余，已定义多个逐级完善的等级。实践目标是在冗余与性能之间取得最佳平衡，最理想结果取决于数据库系统类型、使用频率或最常用登录方法。", "mnemonic": "分解表、减冗余、平衡性能", "useImg": false}, {"front": "Ensembl和Gene Ontology数据库各有什么特点？", "back": "Ensembl由EBI与Wellcome Trust Sanger Institute联合开发，是基因注释数据库，真核生物基因组数据主要集中在脊椎动物。数据可直接访问MySQL服务器获取，但因结构纲目复杂，通常建议通过专用Perl API访问。Gene Ontology数据库也是基于MySQL分布的关系型数据库，将基因组术语整理成本体结构，建立在细胞成分、生物过程、分子功能三个层面。", "mnemonic": "Ensembl脊椎注释，GO三层面本体", "useImg": false}, {"front": "Entrez系统中硬连接（hard link）和软连接（soft link）分别指什么？", "back": "硬连接指点击圆圈显示与其他数据库的链接信息，即不同数据库之间的链接。软连接又称neighbor，指各数据库内部数据间预先运算好的与某记录相似的其他记录。", "mnemonic": "硬连跨库，软连库内相似", "useImg": false}]}, {"i": 11, "sec": "第三节 生物学数据库的检索", "title": "Entrez全局检索与单库精确检索", "notes": "Entrez提供全局检索（Global Search），页面列举全部可查询的Entrez数据库，分为6大类共38个小类。第一类Literature包括书籍、PubMed文献、PubMed Central全文、MeSH和NLM书目。用户在输入框输入关键词点击Search，页面返回查询结果在各数据库中的数量，点击特定数据库即可查看该库结果。全局检索可对检索词进行多库宽泛检索，但结果不精确；精确检索须针对特定数据库，采用特殊方法，如使用布尔操作符连接一个或多个搜索域。在NCBI主页搜索框旁的下拉菜单可选择数据库，也可在主页地址后加数据库名直达子库主页。", "page": 30, "level": "掌握", "img": "assets/img/ch02/p030.jpg", "anim": null, "fig": null, "points": ["在单个Entrez数据库主页可进行更精确的检索。", "常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等，将检索限定在特定字段；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等。", "检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter]”。"], "check": {"q": "关于Entrez全局检索与单库精确检索，下列说法正确的是？", "o": ["A. 全局检索页面列举全部可查询的Entrez数据库，分为6大类共38个小类", "B. 全局检索结果非常精确，可直接替代单库精确检索", "C. 第一类Literature只包括PubMed文献，不包括书籍和MeSH", "D. 精确检索无须针对特定数据库，也不需要特殊方法"], "a": "A", "e": "Entrez提供全局检索，页面列举全部可查询的Entrez数据库，分为6大类共38个小类；第一类Literature包括书籍、PubMed文献、PubMed Central全文、MeSH和NLM书目；全局检索可多库宽泛检索，但结果不精确；精确检索须针对特定数据库，采用特殊方法，如使用布尔操作符等。"}, "cards": [{"front": "Entrez全局检索与单库精确检索有何区别？", "back": "全局检索（Global Search）页面列举全部可查询的Entrez数据库，分为6大类共38个小类。输入关键词点击Search，页面返回查询结果在各数据库中的数量，点击特定数据库即可查看该库结果。全局检索可对检索词进行多库宽泛检索，但结果不精确；精确检索须针对单个数据库进行。", "mnemonic": "全局宽泛，单库精确", "useImg": false}, {"front": "在单个Entrez数据库中进行精确检索的常用策略有哪些？", "back": "使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等。检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter]”。", "mnemonic": "布尔、字段、引号、Limits", "useImg": false}]}, {"i": 12, "sec": "第三节 生物学数据库的检索", "title": "Entrez检索的布尔逻辑与字段限定", "notes": "在单个Entrez数据库主页可进行更精确的检索。常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等，将检索限定在特定字段；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等。检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter] AND 2024/01/01:2024/01/31[PDAT]”。易错点：布尔操作符须大写；字段标签须用方括号；不同数据库支持的字段与语法不同，需查阅各自帮助文档。", "page": 30, "level": "掌握", "img": "assets/img/ch02/p030.jpg", "anim": null, "fig": null, "points": ["在单个Entrez数据库主页可进行更精确的检索。", "常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等，将检索限定在特定字段；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等。", "检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter]”。"], "check": {"q": "在单个Entrez数据库主页进行精确检索时，下列策略不常用的是？", "o": ["A. 使用布尔操作符AND、OR、NOT连接检索词", "B. 使用字段限定，如[Organism]、[Gene Name]、[Publication Date]", "C. 使用引号进行短语检索", "D. 删除所有检索词，直接浏览全部记录"], "a": "D", "e": "在单个Entrez数据库主页可进行更精确的检索，常用策略包括使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等。"}, "cards": [{"front": "Entrez全局检索与单库精确检索有何区别？", "back": "全局检索（Global Search）页面列举全部可查询的Entrez数据库，分为6大类共38个小类。输入关键词点击Search，页面返回查询结果在各数据库中的数量，点击特定数据库即可查看该库结果。全局检索可对检索词进行多库宽泛检索，但结果不精确；精确检索须针对单个数据库进行。", "mnemonic": "全局宽泛，单库精确", "useImg": false}, {"front": "在单个Entrez数据库中进行精确检索的常用策略有哪些？", "back": "使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等。检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter]”。", "mnemonic": "布尔、字段、引号、Limits", "useImg": false}]}, {"i": 13, "sec": "第三节 生物学数据库的检索", "title": "SRS检索系统与数据库检索策略", "notes": "SRS（Sequence Retrieval System）是另一常用生物学数据库检索系统，最初由欧洲分子生物学实验室开发，可整合检索多种异构数据库。其核心思想是通过统一查询语言和索引，将不同来源、不同格式的数据库链接起来，支持跨库检索与结果导航。与Entrez类似，SRS利用数据库间的交叉引用实现相关记录跳转。检索策略上，一般先明确信息需求，选择合适数据库，再构造检索式（关键词、布尔逻辑、字段限定），最后评估结果并迭代优化。易错点：不同检索系统语法不同，跨库检索时需注意字段名与索引差异。", "page": 31, "level": "了解", "img": "assets/img/ch02/p031.jpg", "anim": null, "fig": null, "points": ["使用序列数据库检索时需注意：①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。", "此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。", "掌握这些要点可提高检索效率与结果可靠性。"], "check": {"q": "关于SRS检索系统与数据库检索策略，下列说法正确的是？", "o": ["A. SRS最初由NCBI开发，只能检索单一数据库", "B. SRS通过统一查询语言和索引，将不同来源、不同格式的数据库链接起来，支持跨库检索与结果导航", "C. SRS不能利用数据库间的交叉引用实现相关记录跳转", "D. 检索策略上应先评估结果，再明确信息需求，最后选择数据库"], "a": "B", "e": "SRS最初由欧洲分子生物学实验室开发，可整合检索多种异构数据库；其核心思想是通过统一查询语言和索引，将不同来源、不同格式的数据库链接起来，支持跨库检索与结果导航；与Entrez类似，SRS利用数据库间的交叉引用实现相关记录跳转；检索策略上一般先明确信息需求，选择合适数据库，再构造检索式，最后评估结果并迭代优化。"}, "cards": [{"front": "SRS检索系统的核心思想是什么？", "back": "SRS（Sequence Retrieval System）最初由欧洲分子生物学实验室开发，可整合检索多种异构数据库。其核心思想是通过统一查询语言和索引，将不同来源、不同格式的数据库链接起来，支持跨库检索与结果导航。与Entrez类似，SRS利用数据库间的交叉引用实现相关记录跳转。", "mnemonic": "统一查询、跨库链接", "useImg": false}, {"front": "BLAST和FASTA有何异同？BLAST常用程序有哪些？", "back": "BLAST和FASTA均基于局部比对进行序列相似性检索，但采用不同的词长与打分策略。BLAST通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx。两者均输出比对得分、E值（期望值）和相似性百分比等统计量。", "mnemonic": "BLAST五程序：n、p、x、tn、tx", "useImg": false}, {"front": "多序列比对常用工具有哪些？系统发生树构建方法主要有哪些？", "back": "多序列比对（MSA）常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等。系统发生树构建方法主要有距离法（如邻接法NJ）、最大简约法（MP）、最大似然法（ML）和贝叶斯推断。NJ基于距离矩阵快速构建；ML和贝叶斯基于概率模型，计算量大但统计基础更严谨。", "mnemonic": "比对Clustal/MUSCLE/MAFFT，建树NJ/MP/ML/贝叶斯", "useImg": false}, {"front": "使用序列数据库检索时需注意哪些常见问题？", "back": "①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。", "mnemonic": "版本、冗余、注释、物种、核查", "useImg": false}]}, {"i": 14, "sec": "第三节 生物学数据库的检索", "title": "序列相似性检索与BLAST、FASTA", "notes": "序列相似性检索是数据库检索的核心任务之一。BLAST（Basic Local Alignment Search Tool）基于局部比对，通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx。FASTA是另一类相似性检索程序，也基于局部比对，但采用不同的词长与打分策略。两者均输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。易错点：BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "page": 31, "level": "掌握", "img": "assets/img/ch02/p031.jpg", "anim": null, "fig": null, "points": ["使用序列数据库检索时需注意：①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。", "此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。", "掌握这些要点可提高检索效率与结果可靠性。"], "check": {"q": "关于序列相似性检索与BLAST、FASTA，下列说法正确的是？", "o": ["A. BLAST基于全局比对，FASTA基于多序列比对", "B. BLAST常用程序包括blastn、blastp、blastx、tblastn、tblastx", "C. E值越大表示比对结果越显著", "D. FASTA与BLAST均不输出E值"], "a": "B", "e": "BLAST基于局部比对，通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx；FASTA也是基于局部比对的相似性检索程序，但采用不同的词长与打分策略；两者均输出比对得分、E值和相似性百分比，E值越小越显著。"}, "cards": [{"front": "SRS检索系统的核心思想是什么？", "back": "SRS（Sequence Retrieval System）最初由欧洲分子生物学实验室开发，可整合检索多种异构数据库。其核心思想是通过统一查询语言和索引，将不同来源、不同格式的数据库链接起来，支持跨库检索与结果导航。与Entrez类似，SRS利用数据库间的交叉引用实现相关记录跳转。", "mnemonic": "统一查询、跨库链接", "useImg": false}, {"front": "BLAST和FASTA有何异同？BLAST常用程序有哪些？", "back": "BLAST和FASTA均基于局部比对进行序列相似性检索，但采用不同的词长与打分策略。BLAST通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx。两者均输出比对得分、E值（期望值）和相似性百分比等统计量。", "mnemonic": "BLAST五程序：n、p、x、tn、tx", "useImg": false}, {"front": "多序列比对常用工具有哪些？系统发生树构建方法主要有哪些？", "back": "多序列比对（MSA）常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等。系统发生树构建方法主要有距离法（如邻接法NJ）、最大简约法（MP）、最大似然法（ML）和贝叶斯推断。NJ基于距离矩阵快速构建；ML和贝叶斯基于概率模型，计算量大但统计基础更严谨。", "mnemonic": "比对Clustal/MUSCLE/MAFFT，建树NJ/MP/ML/贝叶斯", "useImg": false}, {"front": "使用序列数据库检索时需注意哪些常见问题？", "back": "①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。", "mnemonic": "版本、冗余、注释、物种、核查", "useImg": false}]}, {"i": 15, "sec": "第三节 生物学数据库的检索", "title": "多序列比对与系统发生分析工具", "notes": "多序列比对（MSA）将多条序列按同源位点对齐，常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等。比对结果可用于识别保守区、构建系统发生树。系统发生树构建方法主要有距离法（如邻接法NJ）、最大简约法（MP）、最大似然法（ML）和贝叶斯推断。NJ基于距离矩阵快速构建；ML和贝叶斯基于概率模型，计算量大但统计基础更严谨。易错点：MSA质量直接影响树的可信度；不同方法可能得到不同拓扑结构，需结合自举值（bootstrap）评估支持率。", "page": 31, "level": "理解", "img": "assets/img/ch02/p031.jpg", "anim": null, "fig": null, "points": ["使用序列数据库检索时需注意：①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。", "此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。", "掌握这些要点可提高检索效率与结果可靠性。"], "check": {"q": "关于多序列比对与系统发生分析工具，下列说法正确的是？", "o": ["A. 多序列比对常用工具包括Clustal、MUSCLE、MAFFT等", "B. 邻接法NJ属于最大似然法的一种", "C. 最大似然法和贝叶斯推断计算量小，统计基础较弱", "D. MSA质量不影响系统发生树的可信度"], "a": "A", "e": "多序列比对常用工具包括Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等；系统发生树构建方法主要有距离法（如邻接法NJ）、最大简约法（MP）、最大似然法（ML）和贝叶斯推断；NJ基于距离矩阵快速构建；ML和贝叶斯基于概率模型，计算量大但统计基础更严谨；MSA质量直接影响树的可信度。"}, "cards": [{"front": "SRS检索系统的核心思想是什么？", "back": "SRS（Sequence Retrieval System）最初由欧洲分子生物学实验室开发，可整合检索多种异构数据库。其核心思想是通过统一查询语言和索引，将不同来源、不同格式的数据库链接起来，支持跨库检索与结果导航。与Entrez类似，SRS利用数据库间的交叉引用实现相关记录跳转。", "mnemonic": "统一查询、跨库链接", "useImg": false}, {"front": "BLAST和FASTA有何异同？BLAST常用程序有哪些？", "back": "BLAST和FASTA均基于局部比对进行序列相似性检索，但采用不同的词长与打分策略。BLAST通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx。两者均输出比对得分、E值（期望值）和相似性百分比等统计量。", "mnemonic": "BLAST五程序：n、p、x、tn、tx", "useImg": false}, {"front": "多序列比对常用工具有哪些？系统发生树构建方法主要有哪些？", "back": "多序列比对（MSA）常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等。系统发生树构建方法主要有距离法（如邻接法NJ）、最大简约法（MP）、最大似然法（ML）和贝叶斯推断。NJ基于距离矩阵快速构建；ML和贝叶斯基于概率模型，计算量大但统计基础更严谨。", "mnemonic": "比对Clustal/MUSCLE/MAFFT，建树NJ/MP/ML/贝叶斯", "useImg": false}, {"front": "使用序列数据库检索时需注意哪些常见问题？", "back": "①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。", "mnemonic": "版本、冗余、注释、物种、核查", "useImg": false}]}, {"i": 16, "sec": "第三节 生物学数据库的检索", "title": "序列数据库检索中的常见问题与注意事项", "notes": "使用序列数据库检索时需注意：①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。掌握这些要点可提高检索效率与结果可靠性。", "page": 31, "level": "理解", "img": "assets/img/ch02/p031.jpg", "anim": null, "fig": null, "points": ["使用序列数据库检索时需注意：①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。", "此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。", "掌握这些要点可提高检索效率与结果可靠性。"], "check": {"q": "关于序列数据库检索中的常见问题与注意事项，下列说法错误的是？", "o": ["A. 需注意数据库版本与更新日期，不同版本序列可能不同", "B. 同一基因可能存在多条序列，需选择参考序列（RefSeq）", "C. 自动注释一定正确，检索结果可直接采信，无需人工核查", "D. 序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性"], "a": "C", "e": "使用序列数据库检索时需注意：数据库版本与更新日期；冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；注释质量，自动注释可能错误，应结合实验证据；物种与分类学信息，确保TaxID正确；检索结果需人工核查，不能盲目采信；序列格式影响后续分析工具的兼容性。"}, "cards": [{"front": "SRS检索系统的核心思想是什么？", "back": "SRS（Sequence Retrieval System）最初由欧洲分子生物学实验室开发，可整合检索多种异构数据库。其核心思想是通过统一查询语言和索引，将不同来源、不同格式的数据库链接起来，支持跨库检索与结果导航。与Entrez类似，SRS利用数据库间的交叉引用实现相关记录跳转。", "mnemonic": "统一查询、跨库链接", "useImg": false}, {"front": "BLAST和FASTA有何异同？BLAST常用程序有哪些？", "back": "BLAST和FASTA均基于局部比对进行序列相似性检索，但采用不同的词长与打分策略。BLAST通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx。两者均输出比对得分、E值（期望值）和相似性百分比等统计量。", "mnemonic": "BLAST五程序：n、p、x、tn、tx", "useImg": false}, {"front": "多序列比对常用工具有哪些？系统发生树构建方法主要有哪些？", "back": "多序列比对（MSA）常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等。系统发生树构建方法主要有距离法（如邻接法NJ）、最大简约法（MP）、最大似然法（ML）和贝叶斯推断。NJ基于距离矩阵快速构建；ML和贝叶斯基于概率模型，计算量大但统计基础更严谨。", "mnemonic": "比对Clustal/MUSCLE/MAFFT，建树NJ/MP/ML/贝叶斯", "useImg": false}, {"front": "使用序列数据库检索时需注意哪些常见问题？", "back": "①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。", "mnemonic": "版本、冗余、注释、物种、核查", "useImg": false}]}], "mcq": [{"id": "ch02_mcq_1", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "在数据库记录中，描述某一类数据特性或属性的类别称为：", "o": ["A. 值（value）", "B. 字段（field）", "C. 条目（entry）", "D. 记录（record）"], "a": "B", "e": "字段（field）是描述数据特性或属性的类别，如基因名、物种；值是字段的具体内容；记录/条目是描述一个实体的完整数据集合。", "kp": "ch02_s0_0"}, {"id": "ch02_mcq_2", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "下列属于一级数据库的是：", "o": ["A. RefSeq", "B. UniProt KnowledgeBase", "C. GenBank", "D. Pfam"], "a": "C", "e": "GenBank是典型的核酸序列一级数据库，存储实验原始数据。RefSeq和UniProt KnowledgeBase是二级数据库，Pfam是序列特征数据库。", "kp": "ch02_s0_3"}, {"id": "ch02_mcq_3", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "UniProt平面文件Entry中，表示Entry结束的符号是：", "o": ["A. //", "B. ##", "C. --", "D. **"], "a": "A", "e": "UniProt Flat File中，每个Entry以“//”表示结束。每行开头为两个字符的字段标识符，如ID、AC、DT等。", "kp": "ch02_s0_5"}, {"id": "ch02_mcq_4", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "关于平面文件格式（Flat File）的描述，错误的是：", "o": ["A. 通常使用ASCII字符", "B. 通用性强，便于跨平台传输", "C. 存储空间利用率通常优于关系型数据库表", "D. 检索时可能需要通读整个文件"], "a": "C", "e": "平面文件在存储空间需求上并不占优势，关系型数据库表或XML文件可能更紧凑。其优势在于通用性和可解析性。", "kp": "ch02_s0_4"}, {"id": "ch02_mcq_5", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "二级数据库与一级数据库的主要区别在于：", "o": ["A. 二级数据库只存储核酸序列", "B. 二级数据库在一级数据库基础上经计算加工并增加人工注释", "C. 二级数据库不包含任何注释", "D. 二级数据库只能通过实验获得数据"], "a": "B", "e": "二级数据库在一级数据库信息基础上进行计算加工并增加人为注释，如RefSeq、UniProt KnowledgeBase。其注释可能由程序自动计算，使用时需谨慎。", "kp": "ch02_s0_3"}, {"id": "ch02_mcq_6", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "Entrez系统中，预先运算好的与某记录相似的其他记录之间的连接称为：", "o": ["A. 硬连接（hard link）", "B. 软连接（soft link）", "C. 超链接（hyperlink）", "D. 外键（foreign key）"], "a": "B", "e": "软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录，如核酸序列经BLAST预运算后的相关序列。硬连接指点击圆圈显示的不同数据库间的链接。", "kp": "ch02_s0_10"}, {"id": "ch02_mcq_7", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "下列不属于Entrez全局检索第一类（Literature）的是：", "o": ["A. PubMed", "B. PubMed Central", "C. MeSH", "D. GenBank"], "a": "D", "e": "Entrez全局检索第一类Literature包括书籍、PubMed、PubMed Central、MeSH和NLM书目。GenBank属于核酸序列数据库，不在Literature类。", "kp": "ch02_s0_11"}, {"id": "ch02_mcq_8", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "关于BLAST的描述，正确的是：", "o": ["A. BLAST保证找到最优比对结果", "B. BLAST基于全局比对算法", "C. BLAST是启发式局部比对工具，输出E值", "D. BLAST只能用于核酸序列检索"], "a": "C", "e": "BLAST是基于局部比对的启发式算法，不保证最优比对，输出比对得分、E值和相似性百分比。它有blastn、blastp等多种程序，可用于核酸和蛋白质检索。", "kp": "ch02_s0_14"}, {"id": "ch02_mcq_9", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "Ensembl数据库通常建议通过什么方式访问？", "o": ["A. 直接读取平面文件", "B. 专用Perl API", "C. FTP下载全部数据", "D. 电子邮件查询"], "a": "B", "e": "Ensembl数据可直接访问MySQL服务器，但由于结构纲目复杂，通常建议通过专用Perl API访问。它由EBI与Wellcome Trust Sanger Institute联合开发。", "kp": "ch02_s0_9"}, {"id": "ch02_mcq_10", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "构建系统发生树时，基于距离矩阵快速构建的方法是：", "o": ["A. 最大似然法（ML）", "B. 贝叶斯推断", "C. 邻接法（NJ）", "D. 最大简约法（MP）"], "a": "C", "e": "邻接法（NJ）基于距离矩阵快速构建系统发生树。ML和贝叶斯基于概率模型，计算量大但统计基础更严谨；MP基于最小进化步数假设。", "kp": "ch02_s0_15"}], "judge": [{"id": "ch02_judge_1", "modI": 0, "q": "字段是属性类别，值是具体内容，二者可以混淆。", "a": "错", "e": "字段是属性类别，值是具体内容，二者不可混淆；记录与条目同义。", "kp": "ch02_s0_0"}, {"id": "ch02_judge_2", "modI": 0, "q": "平面文件格式即纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode。", "a": "对", "e": "平面文件格式即纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode；数据被组织为若干Entry（记录/条目），每个Entry描述一个数据实体。", "kp": "ch02_s0_4"}, {"id": "ch02_judge_3", "modI": 0, "q": "二级数据库的注释等同于实验证实。", "a": "错", "e": "二级库注释不等于实验证实；自动计算注释可能误导，使用时需谨慎。", "kp": "ch02_s0_3"}, {"id": "ch02_judge_4", "modI": 0, "q": "UniProt的Flat File Entry以“//”表示Entry结束。", "a": "对", "e": "UniProt的Flat File Entry由一系列文本行组成，以“//”表示Entry结束。", "kp": "ch02_s0_5"}, {"id": "ch02_judge_5", "modI": 0, "q": "关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询。", "a": "对", "e": "关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高。", "kp": "ch02_s0_6"}, {"id": "ch02_judge_6", "modI": 0, "q": "Entrez中，各数据库内部数据间存在硬连接（hard link），又称neighbor，指预先运算好的与某记录相似的其他记录。", "a": "错", "e": "Entrez中，各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）。", "kp": "ch02_s0_10"}, {"id": "ch02_judge_7", "modI": 0, "q": "在Entrez检索中，布尔操作符须大写，字段标签须用方括号。", "a": "对", "e": "易错点：布尔操作符须大写；字段标签须用方括号；不同数据库支持的字段与语法不同，需查阅各自帮助文档。", "kp": "ch02_s0_12"}, {"id": "ch02_judge_8", "modI": 0, "q": "BLAST是精确算法，保证找到最优比对。", "a": "错", "e": "BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_14"}, {"id": "ch02_judge_9", "modI": 0, "q": "E值越小越显著。", "a": "对", "e": "BLAST与FASTA均输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。", "kp": "ch02_s0_14"}, {"id": "ch02_judge_10", "modI": 0, "q": "多序列比对质量不影响系统发生树的可信度。", "a": "错", "e": "MSA质量直接影响树的可信度；不同方法可能得到不同拓扑结构，需结合自举值（bootstrap）评估支持率。", "kp": "ch02_s0_15"}], "fill": [{"id": "ch02_fill_1", "modI": 0, "q": "数据库的基本单位是________，一条记录描述一个实体；记录由若干________组成，字段是描述属性的类别；________是字段的具体内容。", "a": "记录,字段,值", "kp": "ch02_s0_0"}, {"id": "ch02_fill_2", "modI": 0, "q": "生物学数据库采用4种结构类型：________、关系型数据库、面向对象数据库和基于Internet的________。", "a": "平面文件,XML", "kp": "ch02_s0_1"}, {"id": "ch02_fill_3", "modI": 0, "q": "按存放数据类型，生物学数据库可分为：序列数据库（如GenBank、Swiss-Prot）、三维结构数据库（如________）、文献数据库（如NCBI PubMed）、序列特征数据库（如PROSITE、Pfam）、基因组图谱数据库（如MapViewer、Ensembl）、表达谱数据库等。", "a": "PDB", "kp": "ch02_s0_2"}, {"id": "ch02_fill_4", "modI": 0, "q": "一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库________。", "a": "PDB", "kp": "ch02_s0_3"}, {"id": "ch02_fill_5", "modI": 0, "q": "UniProt的Flat File Entry由一系列文本行组成，以“________”表示Entry结束；每行开头为两个字符的字段标识符，其中ID行给出唯一标识、状态与序列长度（氨基酸残基数）；AC行列出登录号；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI ________。", "a": "//,TaxID", "kp": "ch02_s0_5"}, {"id": "ch02_fill_6", "modI": 0, "q": "Entrez提供全局检索（Global Search），页面列举全部可查询的Entrez数据库，分为6大类共38个小类；第一类Literature包括书籍、PubMed文献、PubMed Central全文、MeSH和NLM书目；全局检索可对检索词进行多库宽泛检索，但结果不精确；精确检索须针对特定数据库，采用特殊方法，如使用________操作符连接一个或多个搜索域。", "a": "布尔", "kp": "ch02_s0_11"}, {"id": "ch02_fill_7", "modI": 0, "q": "在单个Entrez数据库主页可进行更精确的检索，常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等，将检索限定在特定字段；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等；检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter] AND 2024/01/01:2024/01/31[PDAT]”；易错点：布尔操作符须________；字段标签须用________。", "a": "大写,方括号", "kp": "ch02_s0_12"}, {"id": "ch02_fill_8", "modI": 0, "q": "序列相似性检索是数据库检索的核心任务之一；BLAST基于局部比对，通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx；FASTA是另一类相似性检索程序，也基于局部比对，但采用不同的词长与打分策略；两者均输出比对得分、E值（期望值）和相似性百分比；E值越________越显著。", "a": "小", "kp": "ch02_s0_14"}], "short": [{"id": "ch02_short_1", "modI": 0, "q": "简述生物学数据库按存储内容层次的分类，并举例说明一级数据库与二级数据库的区别。", "a": "按存储内容层次分为一级数据库、二级数据库和专用数据库。一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。二级数据库在一级数据库基础上经计算加工并增加人工注释，如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）。二级库功能与结构注释突出，但自动计算注释可能误导，使用时需谨慎；二级库注释不等于实验证实。", "kp": "ch02_s0_2"}, {"id": "ch02_short_2", "modI": 0, "q": "简述UniProt平面文件Entry的结构与常见字段标识符的含义。", "a": "UniProt的Flat File Entry由一系列文本行组成，以“//”表示Entry结束；每行开头为两个字符的字段标识符：ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DT行记录日期与版本；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI TaxID；RN/RP/RX/RA/RT/RL行描述文献。理解字段标识符是解析平面文件、编写脚本提取信息的基础。", "kp": "ch02_s0_5"}, {"id": "ch02_short_3", "modI": 0, "q": "简述Entrez全局检索与单库精确检索的区别，并列举单库精确检索的常用策略。", "a": "Entrez提供全局检索（Global Search），页面列举全部可查询的Entrez数据库，分为6大类共38个小类；用户在输入框输入关键词点击Search，页面返回查询结果在各数据库中的数量，点击特定数据库即可查看该库结果；全局检索可对检索词进行多库宽泛检索，但结果不精确。精确检索须针对特定数据库，采用特殊方法，如使用布尔操作符连接一个或多个搜索域。在单个Entrez数据库主页可进行更精确的检索，常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等，将检索限定在特定字段；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等；检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter] AND 2024/01/01:2024/01/31[PDAT]”。易错点：布尔操作符须大写；字段标签须用方括号；不同数据库支持的字段与语法不同，需查阅各自帮助文档。", "kp": "ch02_s0_11"}, {"id": "ch02_short_4", "modI": 0, "q": "简述BLAST与FASTA的异同及使用时的注意事项。", "a": "相同点：BLAST与FASTA均属序列相似性检索程序，基于局部比对，输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。不同点：BLAST（Basic Local Alignment Search Tool）通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx；FASTA采用不同的词长与打分策略。注意事项：BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_14"}, {"id": "ch02_short_5", "modI": 0, "q": "简述多序列比对与系统发生分析的关系及常用方法与注意事项。", "a": "多序列比对（MSA）将多条序列按同源位点对齐，常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等；比对结果可用于识别保守区、构建系统发生树。系统发生树构建方法主要有距离法（如邻接法NJ）、最大简约法（MP）、最大似然法（ML）和贝叶斯推断；NJ基于距离矩阵快速构建；ML和贝叶斯基于概率模型，计算量大但统计基础更严谨。注意事项：MSA质量直接影响树的可信度；不同方法可能得到不同拓扑结构，需结合自举值（bootstrap）评估支持率。", "kp": "ch02_s0_15"}], "calc": [{"id": "ch02_calc_1", "modI": 0, "q": "论述生物学数据库检索中数据格式的通用性与紧凑性权衡，并结合平面文件、关系型数据库和XML说明其优缺点。", "a": "信息存储需控制两方面：数据编译为字节的方式（数据格式）以及能编码/解码该数据的程序。二者紧密相关：复杂全能格式若无现成程序支持则无意义；过于简单紧凑的格式又限制数据操作功能。平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。因此格式选择需在通用性、可解析性、存储效率与传输效率之间权衡，这是生物信息学数据管理面临的难题之一。", "steps": "1. 数据格式与程序支持的关系；2. 平面文件的通用性与空间利用率；3. 关系型表或XML的紧凑性；4. 网络传输时紧凑性的重要性；5. 格式选择的权衡。", "kp": "ch02_s0_7"}, {"id": "ch02_calc_2", "modI": 0, "q": "论述序列数据库检索中的常见问题与注意事项，并说明如何提高检索效率与结果可靠性。", "a": "使用序列数据库检索时需注意：①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。掌握这些要点可提高检索效率与结果可靠性。", "steps": "1. 数据库版本与更新日期；2. 冗余与参考序列选择；3. 注释质量与实验证据；4. 物种与分类学信息；5. 人工核查；6. 序列格式兼容性。", "kp": "ch02_s0_16"}], "term": [{"id": "ch02_term_1", "modI": 0, "term": "Database", "def": "按一定结构组织、统一管理的数据集合，便于检索与调用；基本单位是记录（record/entry），一条记录描述一个实体（如一条序列、一个蛋白质）；记录由若干字段（field）组成，字段是描述属性的类别，如基因名、物种、创建日期；值（value）是字段的具体内容。", "kp": "ch02_s0_0"}, {"id": "ch02_term_2", "modI": 0, "term": "Flat file database", "def": "以纯文本（通常ASCII，也可含扩展ASCII或Unicode）保存的数据库；数据组织为若干Entry（记录/条目），每个Entry描述一个数据实体；正文行中每列对应明确定义的格式；优势是通用性强、跨平台、便于FTP或电子邮件传输；缺点是存储空间利用率不占优，网络传输时紧凑性成为瓶颈。", "kp": "ch02_s0_4"}, {"id": "ch02_term_3", "modI": 0, "term": "Relational database", "def": "将数据组织为二维表，行对应记录、列对应字段；通过主键与外键建立表间关联；支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高；常见实例有Ensembl和Gene Ontology数据库。", "kp": "ch02_s0_0"}, {"id": "ch02_term_4", "modI": 0, "term": "XML", "def": "可扩展标记语言，用成对标签描述数据的层次结构；兼具可读性与机器可解析性，适合表示复杂嵌套信息及网络交换；但文件较冗长。", "kp": "ch02_s0_1"}, {"id": "ch02_term_5", "modI": 0, "term": "Primary database", "def": "属档案数据库（archive），内容主要是实验原始数据及基本说明；如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。", "kp": "ch02_s0_5"}, {"id": "ch02_term_6", "modI": 0, "term": "Secondary database", "def": "在一级数据库基础上经计算加工并增加人工注释；如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）；二级库功能与结构注释突出，但自动计算注释可能误导，使用时需谨慎；二级库注释不等于实验证实。", "kp": "ch02_s0_0"}, {"id": "ch02_term_7", "modI": 0, "term": "UniProt flat file entry", "def": "由一系列文本行组成，以“//”表示Entry结束；每行开头为两个字符的字段标识符：ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DT行记录日期与版本；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI TaxID；RN/RP/RX/RA/RT/RL行描述文献；理解字段标识符是解析平面文件、编写脚本提取信息的基础。", "kp": "ch02_s0_5"}, {"id": "ch02_term_8", "modI": 0, "term": "Entrez", "def": "由NCBI开发维护，是目前应用最广泛的生物学数据库检索系统之一；利用公共数据库各记录间本身存在的逻辑关系，从多种类型数据的文本信息中找到所需信息；Entrez数据库模型中，圆圈表示各数据库，颜色深浅表示数据量多少；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）；各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录，例如核酸序列经BLAST预运算后每条记录都有相关序列（related sequence）。", "kp": "ch02_s0_10"}, {"id": "ch02_term_9", "modI": 0, "term": "SRS", "def": "Sequence Retrieval System，另一常用生物学数据库检索系统，最初由欧洲分子生物学实验室开发，可整合检索多种异构数据库；核心思想是通过统一查询语言和索引，将不同来源、不同格式的数据库链接起来，支持跨库检索与结果导航；与Entrez类似，SRS利用数据库间的交叉引用实现相关记录跳转。", "kp": "ch02_s0_13"}, {"id": "ch02_term_10", "modI": 0, "term": "BLAST", "def": "Basic Local Alignment Search Tool，基于局部比对，通过寻找高分片段对（HSP）快速搜索数据库中相似序列；常用程序包括blastn、blastp、blastx、tblastn、tblastx；输出比对得分、E值（期望值）和相似性百分比；E值越小越显著；BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_14"}, {"id": "ch02_term_11", "modI": 0, "term": "FASTA", "def": "另一类相似性检索程序，也基于局部比对，但采用不同的词长与打分策略；输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。", "kp": "ch02_s0_14"}, {"id": "ch02_term_12", "modI": 0, "term": "Multiple sequence alignment (MSA)", "def": "将多条序列按同源位点对齐，常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等；比对结果可用于识别保守区、构建系统发生树；MSA质量直接影响树的可信度。", "kp": "ch02_s0_9"}]}], "mcq": [{"id": "ch02_mcq_1", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "在数据库记录中，描述某一类数据特性或属性的类别称为：", "o": ["A. 值（value）", "B. 字段（field）", "C. 条目（entry）", "D. 记录（record）"], "a": "B", "e": "字段（field）是描述数据特性或属性的类别，如基因名、物种；值是字段的具体内容；记录/条目是描述一个实体的完整数据集合。", "kp": "ch02_s0_0"}, {"id": "ch02_mcq_2", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "下列属于一级数据库的是：", "o": ["A. RefSeq", "B. UniProt KnowledgeBase", "C. GenBank", "D. Pfam"], "a": "C", "e": "GenBank是典型的核酸序列一级数据库，存储实验原始数据。RefSeq和UniProt KnowledgeBase是二级数据库，Pfam是序列特征数据库。", "kp": "ch02_s0_3"}, {"id": "ch02_mcq_3", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "UniProt平面文件Entry中，表示Entry结束的符号是：", "o": ["A. //", "B. ##", "C. --", "D. **"], "a": "A", "e": "UniProt Flat File中，每个Entry以“//”表示结束。每行开头为两个字符的字段标识符，如ID、AC、DT等。", "kp": "ch02_s0_5"}, {"id": "ch02_mcq_4", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "关于平面文件格式（Flat File）的描述，错误的是：", "o": ["A. 通常使用ASCII字符", "B. 通用性强，便于跨平台传输", "C. 存储空间利用率通常优于关系型数据库表", "D. 检索时可能需要通读整个文件"], "a": "C", "e": "平面文件在存储空间需求上并不占优势，关系型数据库表或XML文件可能更紧凑。其优势在于通用性和可解析性。", "kp": "ch02_s0_4"}, {"id": "ch02_mcq_5", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "二级数据库与一级数据库的主要区别在于：", "o": ["A. 二级数据库只存储核酸序列", "B. 二级数据库在一级数据库基础上经计算加工并增加人工注释", "C. 二级数据库不包含任何注释", "D. 二级数据库只能通过实验获得数据"], "a": "B", "e": "二级数据库在一级数据库信息基础上进行计算加工并增加人为注释，如RefSeq、UniProt KnowledgeBase。其注释可能由程序自动计算，使用时需谨慎。", "kp": "ch02_s0_3"}, {"id": "ch02_mcq_6", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "Entrez系统中，预先运算好的与某记录相似的其他记录之间的连接称为：", "o": ["A. 硬连接（hard link）", "B. 软连接（soft link）", "C. 超链接（hyperlink）", "D. 外键（foreign key）"], "a": "B", "e": "软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录，如核酸序列经BLAST预运算后的相关序列。硬连接指点击圆圈显示的不同数据库间的链接。", "kp": "ch02_s0_10"}, {"id": "ch02_mcq_7", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "下列不属于Entrez全局检索第一类（Literature）的是：", "o": ["A. PubMed", "B. PubMed Central", "C. MeSH", "D. GenBank"], "a": "D", "e": "Entrez全局检索第一类Literature包括书籍、PubMed、PubMed Central、MeSH和NLM书目。GenBank属于核酸序列数据库，不在Literature类。", "kp": "ch02_s0_11"}, {"id": "ch02_mcq_8", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "关于BLAST的描述，正确的是：", "o": ["A. BLAST保证找到最优比对结果", "B. BLAST基于全局比对算法", "C. BLAST是启发式局部比对工具，输出E值", "D. BLAST只能用于核酸序列检索"], "a": "C", "e": "BLAST是基于局部比对的启发式算法，不保证最优比对，输出比对得分、E值和相似性百分比。它有blastn、blastp等多种程序，可用于核酸和蛋白质检索。", "kp": "ch02_s0_14"}, {"id": "ch02_mcq_9", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "Ensembl数据库通常建议通过什么方式访问？", "o": ["A. 直接读取平面文件", "B. 专用Perl API", "C. FTP下载全部数据", "D. 电子邮件查询"], "a": "B", "e": "Ensembl数据可直接访问MySQL服务器，但由于结构纲目复杂，通常建议通过专用Perl API访问。它由EBI与Wellcome Trust Sanger Institute联合开发。", "kp": "ch02_s0_9"}, {"id": "ch02_mcq_10", "mod": "第二章 生物学数据库及其检索", "modI": 0, "q": "构建系统发生树时，基于距离矩阵快速构建的方法是：", "o": ["A. 最大似然法（ML）", "B. 贝叶斯推断", "C. 邻接法（NJ）", "D. 最大简约法（MP）"], "a": "C", "e": "邻接法（NJ）基于距离矩阵快速构建系统发生树。ML和贝叶斯基于概率模型，计算量大但统计基础更严谨；MP基于最小进化步数假设。", "kp": "ch02_s0_15"}], "judge": [{"id": "ch02_judge_1", "modI": 0, "q": "字段是属性类别，值是具体内容，二者可以混淆。", "a": "错", "e": "字段是属性类别，值是具体内容，二者不可混淆；记录与条目同义。", "kp": "ch02_s0_0"}, {"id": "ch02_judge_2", "modI": 0, "q": "平面文件格式即纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode。", "a": "对", "e": "平面文件格式即纯文本文件，通常使用ASCII字符，也可含扩展ASCII或Unicode；数据被组织为若干Entry（记录/条目），每个Entry描述一个数据实体。", "kp": "ch02_s0_4"}, {"id": "ch02_judge_3", "modI": 0, "q": "二级数据库的注释等同于实验证实。", "a": "错", "e": "二级库注释不等于实验证实；自动计算注释可能误导，使用时需谨慎。", "kp": "ch02_s0_3"}, {"id": "ch02_judge_4", "modI": 0, "q": "UniProt的Flat File Entry以“//”表示Entry结束。", "a": "对", "e": "UniProt的Flat File Entry由一系列文本行组成，以“//”表示Entry结束。", "kp": "ch02_s0_5"}, {"id": "ch02_judge_5", "modI": 0, "q": "关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询。", "a": "对", "e": "关系型数据库将数据组织为二维表，行对应记录、列对应字段，通过主键与外键建立表间关联，支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高。", "kp": "ch02_s0_6"}, {"id": "ch02_judge_6", "modI": 0, "q": "Entrez中，各数据库内部数据间存在硬连接（hard link），又称neighbor，指预先运算好的与某记录相似的其他记录。", "a": "错", "e": "Entrez中，各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）。", "kp": "ch02_s0_10"}, {"id": "ch02_judge_7", "modI": 0, "q": "在Entrez检索中，布尔操作符须大写，字段标签须用方括号。", "a": "对", "e": "易错点：布尔操作符须大写；字段标签须用方括号；不同数据库支持的字段与语法不同，需查阅各自帮助文档。", "kp": "ch02_s0_12"}, {"id": "ch02_judge_8", "modI": 0, "q": "BLAST是精确算法，保证找到最优比对。", "a": "错", "e": "BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_14"}, {"id": "ch02_judge_9", "modI": 0, "q": "E值越小越显著。", "a": "对", "e": "BLAST与FASTA均输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。", "kp": "ch02_s0_14"}, {"id": "ch02_judge_10", "modI": 0, "q": "多序列比对质量不影响系统发生树的可信度。", "a": "错", "e": "MSA质量直接影响树的可信度；不同方法可能得到不同拓扑结构，需结合自举值（bootstrap）评估支持率。", "kp": "ch02_s0_15"}], "fill": [{"id": "ch02_fill_1", "modI": 0, "q": "数据库的基本单位是________，一条记录描述一个实体；记录由若干________组成，字段是描述属性的类别；________是字段的具体内容。", "a": "记录,字段,值", "kp": "ch02_s0_0"}, {"id": "ch02_fill_2", "modI": 0, "q": "生物学数据库采用4种结构类型：________、关系型数据库、面向对象数据库和基于Internet的________。", "a": "平面文件,XML", "kp": "ch02_s0_1"}, {"id": "ch02_fill_3", "modI": 0, "q": "按存放数据类型，生物学数据库可分为：序列数据库（如GenBank、Swiss-Prot）、三维结构数据库（如________）、文献数据库（如NCBI PubMed）、序列特征数据库（如PROSITE、Pfam）、基因组图谱数据库（如MapViewer、Ensembl）、表达谱数据库等。", "a": "PDB", "kp": "ch02_s0_2"}, {"id": "ch02_fill_4", "modI": 0, "q": "一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库________。", "a": "PDB", "kp": "ch02_s0_3"}, {"id": "ch02_fill_5", "modI": 0, "q": "UniProt的Flat File Entry由一系列文本行组成，以“________”表示Entry结束；每行开头为两个字符的字段标识符，其中ID行给出唯一标识、状态与序列长度（氨基酸残基数）；AC行列出登录号；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI ________。", "a": "//,TaxID", "kp": "ch02_s0_5"}, {"id": "ch02_fill_6", "modI": 0, "q": "Entrez提供全局检索（Global Search），页面列举全部可查询的Entrez数据库，分为6大类共38个小类；第一类Literature包括书籍、PubMed文献、PubMed Central全文、MeSH和NLM书目；全局检索可对检索词进行多库宽泛检索，但结果不精确；精确检索须针对特定数据库，采用特殊方法，如使用________操作符连接一个或多个搜索域。", "a": "布尔", "kp": "ch02_s0_11"}, {"id": "ch02_fill_7", "modI": 0, "q": "在单个Entrez数据库主页可进行更精确的检索，常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等，将检索限定在特定字段；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等；检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter] AND 2024/01/01:2024/01/31[PDAT]”；易错点：布尔操作符须________；字段标签须用________。", "a": "大写,方括号", "kp": "ch02_s0_12"}, {"id": "ch02_fill_8", "modI": 0, "q": "序列相似性检索是数据库检索的核心任务之一；BLAST基于局部比对，通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx；FASTA是另一类相似性检索程序，也基于局部比对，但采用不同的词长与打分策略；两者均输出比对得分、E值（期望值）和相似性百分比；E值越________越显著。", "a": "小", "kp": "ch02_s0_14"}], "short": [{"id": "ch02_short_1", "modI": 0, "q": "简述生物学数据库按存储内容层次的分类，并举例说明一级数据库与二级数据库的区别。", "a": "按存储内容层次分为一级数据库、二级数据库和专用数据库。一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。二级数据库在一级数据库基础上经计算加工并增加人工注释，如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）。二级库功能与结构注释突出，但自动计算注释可能误导，使用时需谨慎；二级库注释不等于实验证实。", "kp": "ch02_s0_2"}, {"id": "ch02_short_2", "modI": 0, "q": "简述UniProt平面文件Entry的结构与常见字段标识符的含义。", "a": "UniProt的Flat File Entry由一系列文本行组成，以“//”表示Entry结束；每行开头为两个字符的字段标识符：ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DT行记录日期与版本；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI TaxID；RN/RP/RX/RA/RT/RL行描述文献。理解字段标识符是解析平面文件、编写脚本提取信息的基础。", "kp": "ch02_s0_5"}, {"id": "ch02_short_3", "modI": 0, "q": "简述Entrez全局检索与单库精确检索的区别，并列举单库精确检索的常用策略。", "a": "Entrez提供全局检索（Global Search），页面列举全部可查询的Entrez数据库，分为6大类共38个小类；用户在输入框输入关键词点击Search，页面返回查询结果在各数据库中的数量，点击特定数据库即可查看该库结果；全局检索可对检索词进行多库宽泛检索，但结果不精确。精确检索须针对特定数据库，采用特殊方法，如使用布尔操作符连接一个或多个搜索域。在单个Entrez数据库主页可进行更精确的检索，常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等，将检索限定在特定字段；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等；检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter] AND 2024/01/01:2024/01/31[PDAT]”。易错点：布尔操作符须大写；字段标签须用方括号；不同数据库支持的字段与语法不同，需查阅各自帮助文档。", "kp": "ch02_s0_11"}, {"id": "ch02_short_4", "modI": 0, "q": "简述BLAST与FASTA的异同及使用时的注意事项。", "a": "相同点：BLAST与FASTA均属序列相似性检索程序，基于局部比对，输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。不同点：BLAST（Basic Local Alignment Search Tool）通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx；FASTA采用不同的词长与打分策略。注意事项：BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_14"}, {"id": "ch02_short_5", "modI": 0, "q": "简述多序列比对与系统发生分析的关系及常用方法与注意事项。", "a": "多序列比对（MSA）将多条序列按同源位点对齐，常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等；比对结果可用于识别保守区、构建系统发生树。系统发生树构建方法主要有距离法（如邻接法NJ）、最大简约法（MP）、最大似然法（ML）和贝叶斯推断；NJ基于距离矩阵快速构建；ML和贝叶斯基于概率模型，计算量大但统计基础更严谨。注意事项：MSA质量直接影响树的可信度；不同方法可能得到不同拓扑结构，需结合自举值（bootstrap）评估支持率。", "kp": "ch02_s0_15"}], "calc": [{"id": "ch02_calc_1", "modI": 0, "q": "论述生物学数据库检索中数据格式的通用性与紧凑性权衡，并结合平面文件、关系型数据库和XML说明其优缺点。", "a": "信息存储需控制两方面：数据编译为字节的方式（数据格式）以及能编码/解码该数据的程序。二者紧密相关：复杂全能格式若无现成程序支持则无意义；过于简单紧凑的格式又限制数据操作功能。平面文件通用性强但空间利用率一般；关系型表或XML文件可能更紧凑。当数据通过网络传输时，传输速度成为瓶颈，格式紧凑性变得重要。因此格式选择需在通用性、可解析性、存储效率与传输效率之间权衡，这是生物信息学数据管理面临的难题之一。", "steps": "1. 数据格式与程序支持的关系；2. 平面文件的通用性与空间利用率；3. 关系型表或XML的紧凑性；4. 网络传输时紧凑性的重要性；5. 格式选择的权衡。", "kp": "ch02_s0_7"}, {"id": "ch02_calc_2", "modI": 0, "q": "论述序列数据库检索中的常见问题与注意事项，并说明如何提高检索效率与结果可靠性。", "a": "使用序列数据库检索时需注意：①数据库版本与更新日期，不同版本序列可能不同；②冗余问题，同一基因可能存在多条序列，需选择参考序列（RefSeq）；③注释质量，自动注释可能错误，应结合实验证据；④物种与分类学信息，确保TaxID正确；⑤检索结果需人工核查，不能盲目采信。此外，序列格式（FASTA、GenBank、EMBL等）影响后续分析工具的兼容性。掌握这些要点可提高检索效率与结果可靠性。", "steps": "1. 数据库版本与更新日期；2. 冗余与参考序列选择；3. 注释质量与实验证据；4. 物种与分类学信息；5. 人工核查；6. 序列格式兼容性。", "kp": "ch02_s0_16"}], "term": [{"id": "ch02_term_1", "modI": 0, "term": "Database", "def": "按一定结构组织、统一管理的数据集合，便于检索与调用；基本单位是记录（record/entry），一条记录描述一个实体（如一条序列、一个蛋白质）；记录由若干字段（field）组成，字段是描述属性的类别，如基因名、物种、创建日期；值（value）是字段的具体内容。", "kp": "ch02_s0_0"}, {"id": "ch02_term_2", "modI": 0, "term": "Flat file database", "def": "以纯文本（通常ASCII，也可含扩展ASCII或Unicode）保存的数据库；数据组织为若干Entry（记录/条目），每个Entry描述一个数据实体；正文行中每列对应明确定义的格式；优势是通用性强、跨平台、便于FTP或电子邮件传输；缺点是存储空间利用率不占优，网络传输时紧凑性成为瓶颈。", "kp": "ch02_s0_4"}, {"id": "ch02_term_3", "modI": 0, "term": "Relational database", "def": "将数据组织为二维表，行对应记录、列对应字段；通过主键与外键建立表间关联；支持SQL进行添加、删除、查询；优点是冗余可控、查询高效、并发与事务管理成熟；缺点是结构需预先定义，模式变更成本高；常见实例有Ensembl和Gene Ontology数据库。", "kp": "ch02_s0_0"}, {"id": "ch02_term_4", "modI": 0, "term": "XML", "def": "可扩展标记语言，用成对标签描述数据的层次结构；兼具可读性与机器可解析性，适合表示复杂嵌套信息及网络交换；但文件较冗长。", "kp": "ch02_s0_1"}, {"id": "ch02_term_5", "modI": 0, "term": "Primary database", "def": "属档案数据库（archive），内容主要是实验原始数据及基本说明；如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。", "kp": "ch02_s0_5"}, {"id": "ch02_term_6", "modI": 0, "term": "Secondary database", "def": "在一级数据库基础上经计算加工并增加人工注释；如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）；二级库功能与结构注释突出，但自动计算注释可能误导，使用时需谨慎；二级库注释不等于实验证实。", "kp": "ch02_s0_0"}, {"id": "ch02_term_7", "modI": 0, "term": "UniProt flat file entry", "def": "由一系列文本行组成，以“//”表示Entry结束；每行开头为两个字符的字段标识符：ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DT行记录日期与版本；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI TaxID；RN/RP/RX/RA/RT/RL行描述文献；理解字段标识符是解析平面文件、编写脚本提取信息的基础。", "kp": "ch02_s0_5"}, {"id": "ch02_term_8", "modI": 0, "term": "Entrez", "def": "由NCBI开发维护，是目前应用最广泛的生物学数据库检索系统之一；利用公共数据库各记录间本身存在的逻辑关系，从多种类型数据的文本信息中找到所需信息；Entrez数据库模型中，圆圈表示各数据库，颜色深浅表示数据量多少；点击圆圈显示与其他数据库的链接信息，属硬连接（hard link）；各数据库内部数据间存在软连接（soft link），又称neighbor，指预先运算好的与某记录相似的其他记录，例如核酸序列经BLAST预运算后每条记录都有相关序列（related sequence）。", "kp": "ch02_s0_10"}, {"id": "ch02_term_9", "modI": 0, "term": "SRS", "def": "Sequence Retrieval System，另一常用生物学数据库检索系统，最初由欧洲分子生物学实验室开发，可整合检索多种异构数据库；核心思想是通过统一查询语言和索引，将不同来源、不同格式的数据库链接起来，支持跨库检索与结果导航；与Entrez类似，SRS利用数据库间的交叉引用实现相关记录跳转。", "kp": "ch02_s0_13"}, {"id": "ch02_term_10", "modI": 0, "term": "BLAST", "def": "Basic Local Alignment Search Tool，基于局部比对，通过寻找高分片段对（HSP）快速搜索数据库中相似序列；常用程序包括blastn、blastp、blastx、tblastn、tblastx；输出比对得分、E值（期望值）和相似性百分比；E值越小越显著；BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "kp": "ch02_s0_14"}, {"id": "ch02_term_11", "modI": 0, "term": "FASTA", "def": "另一类相似性检索程序，也基于局部比对，但采用不同的词长与打分策略；输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。", "kp": "ch02_s0_14"}, {"id": "ch02_term_12", "modI": 0, "term": "Multiple sequence alignment (MSA)", "def": "将多条序列按同源位点对齐，常用工具Clustal（如ClustalW、Clustal Omega）、MUSCLE、MAFFT等；比对结果可用于识别保守区、构建系统发生树；MSA质量直接影响树的可信度。", "kp": "ch02_s0_9"}], "preview": {"main": "本章主线是生物学数据库及其检索：从数据库、记录、字段与值等基本概念出发，介绍平面文件、关系型、对象型与XML等数据库结构类型，说明生物学数据库按数据类型和存储内容层次的分类，重点区分一级数据库与二级数据库；进而以UniProt平面文件、Ensembl、Gene Ontology、NCBI Entrez和SRS为例，讲解数据格式、字段标识符、检索语法、布尔逻辑与字段限定；最后延伸到序列相似性检索BLAST/FASTA、多序列比对与系统发生分析工具，以及序列数据库检索中的常见问题与注意事项。", "questions": ["数据库、记录、字段与值之间是什么关系？检索的本质为什么可理解为字段-值条件匹配？", "平面文件、关系型数据库、对象型数据库与XML各有什么优缺点？生物信息学中如何权衡通用性与紧凑性？", "一级数据库与二级数据库有何区别？为什么二级数据库的注释不能等同于实验证实？", "Entrez全局检索与单库精确检索有何不同？如何用布尔操作符和字段限定构造精确检索式？", "BLAST与FASTA有何异同？E值如何解读？多序列比对和系统发生树构建中哪些因素会影响结果可信度？"]}, "appcards": [{"front": "应用/分析题：在GenBank中检索“物种为人（Homo sapiens）、近30天公布、分子类型为mRNA的核酸序列”，应如何理解数据库、记录、字段与值在检索中的作用？", "back": "数据库是按一定结构组织、统一管理的数据集合；基本单位是记录（record/entry），一条记录描述一个实体（如一条序列、一个蛋白质）；记录由字段（field）组成，字段是属性类别，如基因名、物种、创建日期；值是字段的具体内容。检索的本质是用查询语言在库中查找满足“特定字段包含特定内容”条件的记录。该检索可表达为：物种字段值为Homo sapiens、公布日期字段限定近30天、分子类型字段值为mRNA。", "points": "数据库定义；记录/条目同义；字段是属性类别；值是具体内容；检索本质是字段-值条件匹配；能对应到GenBank检索条件。", "mod": 0, "modName": "第二章 生物学数据库及其检索", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：比较平面文件、关系型数据库、对象型数据库与XML在生物信息学数据存储中的特点与适用场景。", "back": "平面文件以纯文本保存，用特殊分隔符区分记录与字段，通用性强、易解析、便于FTP或电子邮件传输，但检索常需通读文件，记录增多或字段复杂时效率低。关系型数据库以表、行、列组织数据，通过键建立关联，支持SQL查询，冗余可控、查询高效、并发与事务管理成熟，但模式需预先定义，变更成本高。对象型数据库适合复杂嵌套数据。XML用成对标签描述层次结构，兼具可读性与机器可解析性，适合复杂嵌套信息及网络交换，但文件较冗长。", "points": "平面文件特点与优缺点；关系型表/行/列、键、SQL；对象型适合复杂嵌套；XML标签层次结构、网络交换；能比较通用性、紧凑性、查询效率与模式变更成本。", "mod": 0, "modName": "第二章 生物学数据库及其检索", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：说明一级数据库与二级数据库的区别，并举例说明二级数据库注释使用时为何需谨慎。", "back": "一级数据库属档案数据库（archive），内容主要是实验原始数据及基本说明，如核酸序列库GenBank、EMBL、DDBJ和蛋白质结构库PDB。二级数据库在一级数据库基础上经计算加工并增加人工注释，如NCBI的RefSeq（同一物种同一基因所有mRNA的一致性序列）、UniProt KnowledgeBase（由专家人工校正的Swiss-Prot与计算预测的TrEMBL组成）。二级库功能与结构注释突出，但自动计算注释可能误导，使用时需谨慎；二级库注释不等于实验证实。", "points": "一级库为档案库、原始数据；二级库经计算加工和人工注释；GenBank/EMBL/DDBJ/PDB为一级库例；RefSeq/UniProt KB为二级库例；Swiss-Prot人工校正、TrEMBL计算预测；注释不等于实验证实。", "mod": 0, "modName": "第二章 生物学数据库及其检索", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：给定一个UniProt平面文件Entry，如何利用字段标识符提取蛋白质名称、基因名、物种、分类学谱系、NCBI TaxID和文献信息？", "back": "UniProt Flat File Entry由一系列文本行组成，以“//”表示Entry结束。每行开头为两个字符的字段标识符：ID行给出唯一标识（如CYC_HUMAN）、状态与序列长度（氨基酸残基数）；AC行列出登录号；DT行记录日期与版本；DE行描述蛋白质名称；GN行给出基因名；OS行给出物种；OC行给出分类学谱系；OX行给出NCBI TaxID；RN/RP/RX/RA/RT/RL行描述文献。解析时按行首标识符定位对应字段并提取值。", "points": "“//”结束Entry；两个字符字段标识符；ID/AC/DT/DE/GN/OS/OC/OX；RN/RP/RX/RA/RT/RL文献行；能按标识符提取目标信息；理解字段标识符是脚本解析基础。", "mod": 0, "modName": "第二章 生物学数据库及其检索", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：在Entrez中进行全局检索与单库精确检索有何不同？如何构造一个较精确的检索式？", "back": "Entrez提供全局检索（Global Search），页面列举全部可查询的Entrez数据库，分为6大类共38个小类；输入关键词点击Search后返回查询结果在各数据库中的数量，点击特定数据库查看该库结果。全局检索可对检索词进行多库宽泛检索，但结果不精确；精确检索须针对特定数据库，采用特殊方法，如使用布尔操作符连接一个或多个搜索域。常用策略包括：使用布尔操作符AND、OR、NOT连接检索词；使用字段限定，如[Organism]、[Gene Name]、[Publication Date]等；使用引号进行短语检索；利用Limits页面限定物种、分子类型、日期范围等。检索式可组合，如“Homo sapiens[Organism] AND mRNA[Filter] AND 2024/01/01:2024/01/31[PDAT]”。", "points": "全局检索多库宽泛、结果不精确；单库精确检索针对特定数据库；布尔操作符AND/OR/NOT；字段限定方括号；短语检索引号；Limits限定物种/分子类型/日期；示例检索式；布尔操作符须大写。", "mod": 0, "modName": "第二章 生物学数据库及其检索", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：BLAST与FASTA在序列相似性检索中有何异同？如何解读E值并选择合适程序？", "back": "BLAST（Basic Local Alignment Search Tool）基于局部比对，通过寻找高分片段对（HSP）快速搜索数据库中相似序列，常用程序包括blastn、blastp、blastx、tblastn、tblastx。FASTA是另一类相似性检索程序，也基于局部比对，但采用不同的词长与打分策略。两者均输出比对得分、E值（期望值）和相似性百分比；E值越小越显著。BLAST是启发式算法，不保证最优比对；E值受数据库大小影响；核酸与蛋白质检索应选择对应程序与打分矩阵。", "points": "BLAST局部比对、HSP、启发式；blastn/blastp/blastx/tblastn/tblastx；FASTA也局部比对但词长与打分策略不同；输出得分、E值、相似性百分比；E值越小越显著且受数据库大小影响；按核酸/蛋白质选择程序和打分矩阵。", "mod": 0, "modName": "第二章 生物学数据库及其检索", "level": "掌握", "src": "生成"}]};